return {
  ok: true,
  message: $json.message || 'Queue schema created successfully',
  next: 'Import and configure workflows 02 and 03.'
};

const request = $json.body ?? {};
const messages = Array.isArray(request.messages) ? request.messages : [];
const clientStream = request?.stream === true;
const clientIncludeUsage = clientStream && request?.stream_options?.include_usage === true;
const waitPollSeconds = Math.max(1, Math.min(60, Math.trunc(Number($json.waitPollSeconds) || 5)));
const waitMaxAttempts = Math.max(1, Math.min(8640, Math.trunc(Number($json.waitMaxAttempts) || 720)));
const jobMaxAttempts = Math.max(1, Math.min(10, Math.trunc(Number($json.jobMaxAttempts) || 3)));
const latestUser = [...messages].reverse().find((message) => message?.role === 'user');
const finalMessage = messages[messages.length - 1];
const latestTool = [finalMessage].find(
  (message) => message?.role === 'tool' &&
    typeof message.tool_call_id === 'string' &&
    /^queue_wait_task_[a-f0-9]{32}$/.test(message.tool_call_id),
);

const resultCommand = typeof latestUser?.content === 'string'
  ? latestUser.content.trim().match(/^\/(?:result|wait)\s+(task_[a-f0-9]{32})$/i)
  : null;
const cancelCommand = typeof latestUser?.content === 'string'
  ? latestUser.content.trim().match(/^\/cancel\s+(task_[a-f0-9]{32})$/i)
  : null;
const listCommand = typeof latestUser?.content === 'string' && /^\/queue$/i.test(latestUser.content.trim());

if (latestTool) {
  return {
    action: 'lookup',
    lookupSource: 'tool',
    taskId: latestTool.tool_call_id.slice('queue_wait_'.length),
    clientStream,
    clientIncludeUsage,
  };
}

if (resultCommand) {
  return { action: 'lookup', lookupSource: 'human', taskId: resultCommand[1].toLowerCase(), clientStream, clientIncludeUsage };
}

if (cancelCommand) {
  return { action: 'cancel', taskId: cancelCommand[1].toLowerCase(), clientStream, clientIncludeUsage };
}

if (listCommand) return { action: 'list', clientStream, clientIncludeUsage };

if (!request || typeof request !== 'object' || Array.isArray(request)) {
  return { action: 'invalid', errorCode: 'invalid_json', errorMessage: 'The request body must be a JSON object.' };
}
if (typeof request.model !== 'string' || request.model.trim() === '') {
  return { action: 'invalid', errorCode: 'missing_model', errorMessage: 'model must be a non-empty string.' };
}
if (!messages.length) {
  return { action: 'invalid', errorCode: 'missing_messages', errorMessage: 'messages must be a non-empty array.' };
}
if (request.stream !== undefined && typeof request.stream !== 'boolean') {
  return { action: 'invalid', errorCode: 'invalid_stream', errorMessage: 'stream must be a boolean when provided.' };
}

const approvedShellNames = ['exec_command', 'run_command', 'bash', 'shell', 'terminal', 'exec'];
const approvedArgumentNames = ['cmd', 'command', 'script'];
let waitingToolName = null;
let waitingToolArg = null;

for (const name of approvedShellNames) {
  const tool = Array.isArray(request.tools)
    ? request.tools.find((candidate) => candidate?.type === 'function' && candidate?.function?.name === name)
    : null;
  if (!tool) continue;
  const properties = tool.function?.parameters?.properties ?? {};
  const argumentName = approvedArgumentNames.find((candidate) => properties[candidate]?.type === 'string');
  if (argumentName) {
    waitingToolName = name;
    waitingToolArg = argumentName;
    break;
  }
}

return {
  action: 'submit',
  requestBody: request,
  model: request.model,
  waitingToolName,
  waitingToolArg,
  clientStream,
  clientIncludeUsage,
  waitPollSeconds,
  waitMaxAttempts,
  jobMaxAttempts,
};

return {
  httpStatus: 400,
  responseJson: {
    error: {
      message: $json.errorMessage,
      type: 'invalid_request_error',
      param: null,
      code: $json.errorCode,
    },
  },
};

function waitCommand(taskId, pollSeconds = 5, maxAttempts = 720) {
  const poll = Math.max(1, Math.min(60, Math.trunc(Number(pollSeconds) || 5)));
  const limit = Math.max(1, Math.min(8640, Math.trunc(Number(maxAttempts) || 720)));
  return "task_id='" + taskId + "'; " +
    "command -v curl >/dev/null 2>&1 || { echo 'curl is required' >&2; exit 127; }; " +
    "command -v jq >/dev/null 2>&1 || { echo 'jq is required' >&2; exit 127; }; " +
    "attempt=0; while [ \"$attempt\" -lt " + limit + " ]; do attempt=$((attempt+1)); " +
    "[ -n \"$OPENAI_API_KEY\" ] || { echo 'OPENAI_API_KEY is required' >&2; exit 127; }; " +
    "[ -n \"$OPENAI_BASE_URL\" ] || { echo 'OPENAI_BASE_URL is required' >&2; exit 127; }; " +
    "response=$(curl --fail --silent --show-error --connect-timeout 10 --max-time 30 -H \"Authorization: Bearer $OPENAI_API_KEY\" \"$OPENAI_BASE_URL/queue/tasks/$task_id\") || exit 1; " +
    "status=$(printf '%s' \"$response\" | jq -r '.status // \"unknown\"'); " +
    "case \"$status\" in " +
    "succeeded) printf '%s' \"$response\" | jq -c '{task_id,status,response_id}'; exit 0;; " +
    "queued|running) sleep " + poll + ";; " +
    "failed|cancelled|expired) printf '%s\\n' \"$response\" >&2; exit 1;; " +
    "*) printf 'Unexpected status: %s\\n' \"$status\" >&2; exit 1;; esac; done; " +
    "echo 'Timed out waiting for queued LLM task' >&2; exit 124";
}

const row = $json;
const now = Math.floor(Date.now() / 1000);
const completion = (content, finishReason = 'stop') => ({
  id: 'chatcmpl-status-' + (row.requested_id || 'unknown'),
  object: 'chat.completion',
  created: now,
  model: row.model || 'queued-local-model',
  choices: [{ index: 0, finish_reason: finishReason, message: { role: 'assistant', content } }],
  usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
});

if (!row.task_id) {
  return {
    httpStatus: 404,
    responseJson: {
      error: { message: 'Unknown or expired task.', type: 'invalid_request_error', param: 'task_id', code: 'task_not_found' },
    },
  };
}

if (row.status === 'succeeded' && row.response_body) {
  const response = typeof row.response_body === 'string' ? JSON.parse(row.response_body) : row.response_body;
  return { httpStatus: 200, responseJson: response };
}

if (row.lookup_source === 'tool' && ['queued', 'running'].includes(row.status) && row.waiting_tool_name && row.waiting_tool_arg) {
  const callId = 'queue_wait_' + row.task_id;
  return {
    httpStatus: 200,
    responseJson: {
      id: 'chatcmpl-wait-' + row.task_id,
      object: 'chat.completion',
      created: now,
      model: row.model,
      choices: [{
        index: 0,
        finish_reason: 'tool_calls',
        message: {
          role: 'assistant',
          content: null,
          tool_calls: [{
            id: callId,
            type: 'function',
            function: {
              name: row.waiting_tool_name,
              arguments: JSON.stringify({ [row.waiting_tool_arg]: waitCommand(row.task_id, row.wait_poll_seconds, row.wait_max_attempts) }),
            },
          }],
        },
      }],
      usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    },
  };
}

const details = row.status === 'queued' && row.position
  ? ' Current queue position: ' + row.position + '.'
  : '';
const error = row.error_body
  ? ' ' + JSON.stringify(row.error_body)
  : '';

return {
  httpStatus: 200,
  responseJson: completion('Task ' + row.task_id + ' is ' + row.status + '.' + details + error),
};

const now = Math.floor(Date.now() / 1000);
const found = Boolean($json.task_id);
const content = !found
  ? 'Unknown or expired task.'
  : $json.status === 'cancelled'
    ? 'Task ' + $json.task_id + ' was cancelled.'
    : 'Task ' + $json.task_id + ' cannot be cancelled because its status is ' + $json.status + '.';

return {
  httpStatus: found ? 200 : 404,
  responseJson: found ? {
    id: 'chatcmpl-cancel-' + $json.requested_id,
    object: 'chat.completion',
    created: now,
    model: $json.model || 'queued-local-model',
    choices: [{ index: 0, finish_reason: 'stop', message: { role: 'assistant', content } }],
    usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  } : {
    error: { message: content, type: 'invalid_request_error', param: 'task_id', code: 'task_not_found' },
  },
};

const jobs = typeof $json.jobs === 'string' ? JSON.parse($json.jobs) : ($json.jobs || []);
return {
  httpStatus: 200,
  responseJson: {
    id: 'chatcmpl-queue-list',
    object: 'chat.completion',
    created: Math.floor(Date.now() / 1000),
    model: 'queued-local-model',
    choices: [{
      index: 0,
      finish_reason: 'stop',
      message: {
        role: 'assistant',
        content: jobs.length ? JSON.stringify(jobs, null, 2) : 'There are no queued or running tasks.',
      },
    }],
    usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  },
};

function waitCommand(taskId, pollSeconds = 5, maxAttempts = 720) {
  const poll = Math.max(1, Math.min(60, Math.trunc(Number(pollSeconds) || 5)));
  const limit = Math.max(1, Math.min(8640, Math.trunc(Number(maxAttempts) || 720)));
  return "task_id='" + taskId + "'; " +
    "command -v curl >/dev/null 2>&1 || { echo 'curl is required' >&2; exit 127; }; " +
    "command -v jq >/dev/null 2>&1 || { echo 'jq is required' >&2; exit 127; }; " +
    "attempt=0; while [ \"$attempt\" -lt " + limit + " ]; do attempt=$((attempt+1)); " +
    "[ -n \"$OPENAI_API_KEY\" ] || { echo 'OPENAI_API_KEY is required' >&2; exit 127; }; " +
    "[ -n \"$OPENAI_BASE_URL\" ] || { echo 'OPENAI_BASE_URL is required' >&2; exit 127; }; " +
    "response=$(curl --fail --silent --show-error --connect-timeout 10 --max-time 30 -H \"Authorization: Bearer $OPENAI_API_KEY\" \"$OPENAI_BASE_URL/queue/tasks/$task_id\") || exit 1; " +
    "status=$(printf '%s' \"$response\" | jq -r '.status // \"unknown\"'); " +
    "case \"$status\" in " +
    "succeeded) printf '%s' \"$response\" | jq -c '{task_id,status,response_id}'; exit 0;; " +
    "queued|running) sleep " + poll + ";; " +
    "failed|cancelled|expired) printf '%s\\n' \"$response\" >&2; exit 1;; " +
    "*) printf 'Unexpected status: %s\\n' \"$status\" >&2; exit 1;; esac; done; " +
    "echo 'Timed out waiting for queued LLM task' >&2; exit 124";
}

const row = $json;
const now = Math.floor(Date.now() / 1000);
const callId = 'queue_wait_' + row.task_id;

if (row.waiting_tool_name && row.waiting_tool_arg) {
  return {
    httpStatus: 200,
    responseJson: {
      id: 'chatcmpl-queued-' + row.task_id,
      object: 'chat.completion',
      created: now,
      model: row.model,
      choices: [{
        index: 0,
        finish_reason: 'tool_calls',
        message: {
          role: 'assistant',
          content: null,
          tool_calls: [{
            id: callId,
            type: 'function',
            function: {
              name: row.waiting_tool_name,
              arguments: JSON.stringify({ [row.waiting_tool_arg]: waitCommand(row.task_id, row.wait_poll_seconds, row.wait_max_attempts) }),
            },
          }],
        },
      }],
      usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    },
  };
}

return {
  httpStatus: 200,
  responseJson: {
    id: 'chatcmpl-queued-' + row.task_id,
    object: 'chat.completion',
    created: now,
    model: row.model,
    choices: [{
      index: 0,
      finish_reason: 'stop',
      message: {
        role: 'assistant',
        content: 'Your request is queued as ' + row.task_id + '. Check it with /result ' + row.task_id + ' or cancel it with /cancel ' + row.task_id + '.',
      },
    }],
    usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  },
};

const normalized = $('Process Chat Request').first().json;
const httpStatus = Number($json.httpStatus || 200);
const response = $json.responseJson ?? {};
const wantsStream = normalized.clientStream === true;
const includeUsage = normalized.clientIncludeUsage === true;
const isChatCompletion = response?.object === 'chat.completion' && Array.isArray(response.choices);

if (!wantsStream || httpStatus < 200 || httpStatus >= 300 || !isChatCompletion) {
  return {
    httpStatus,
    responseBody: JSON.stringify(response),
    contentType: 'application/json; charset=utf-8',
    cacheControl: 'no-store',
  };
}

const base = {
  id: response.id || 'chatcmpl-queued-stream',
  object: 'chat.completion.chunk',
  created: Number(response.created || Math.floor(Date.now() / 1000)),
  model: response.model || 'queued-local-model',
};
if (response.system_fingerprint !== undefined) base.system_fingerprint = response.system_fingerprint;
if (response.service_tier !== undefined) base.service_tier = response.service_tier;

const events = [];
const emit = (choices, extra = {}) => {
  events.push('data: ' + JSON.stringify({ ...base, choices, ...extra }) + '\n\n');
};
const emitText = (index, field, value) => {
  if (value === undefined || value === null || value === '') return;
  const characters = Array.from(typeof value === 'string' ? value : JSON.stringify(value));
  for (let offset = 0; offset < characters.length; offset += 96) {
    emit([{ index, delta: { [field]: characters.slice(offset, offset + 96).join('') }, finish_reason: null }]);
  }
};

for (const choice of response.choices) {
  const index = Number(choice.index || 0);
  const message = choice.message || {};
  const openingDelta = { role: message.role || 'assistant' };
  if (message.name !== undefined) openingDelta.name = message.name;
  emit([{ index, delta: openingDelta, finish_reason: null }]);

  emitText(index, 'reasoning_content', message.reasoning_content);
  emitText(index, 'content', message.content);
  emitText(index, 'refusal', message.refusal);

  if (message.function_call) {
    emit([{
      index,
      delta: {
        function_call: {
          name: message.function_call.name || '',
          arguments: message.function_call.arguments || '',
        },
      },
      finish_reason: null,
    }]);
  }

  for (const [toolIndex, toolCall] of (message.tool_calls || []).entries()) {
    emit([{
      index,
      delta: {
        tool_calls: [{
          index: toolIndex,
          id: toolCall.id,
          type: toolCall.type || 'function',
          function: {
            name: toolCall.function?.name || '',
            arguments: toolCall.function?.arguments || '',
          },
        }],
      },
      finish_reason: null,
    }]);
  }

  emit([{
    index,
    delta: {},
    finish_reason: choice.finish_reason || (message.tool_calls?.length ? 'tool_calls' : 'stop'),
  }]);
}

if (includeUsage && response.usage) emit([], { usage: response.usage });
events.push('data: [DONE]\n\n');

return {
  httpStatus,
  responseBody: events.join(''),
  contentType: 'text/event-stream; charset=utf-8',
  cacheControl: 'no-cache, no-transform',
};

const taskId = String($json.params?.taskId || '').toLowerCase();
if (!/^task_[a-f0-9]{32}$/.test(taskId)) {
  return { valid: false, taskId, responseJson: { error: { message: 'Invalid task ID.', type: 'invalid_request_error', param: 'task_id', code: 'invalid_task_id' } }, httpStatus: 400 };
}
return { valid: true, taskId };

if (!$json.task_id) {
  return {
    httpStatus: 404,
    responseJson: { error: { message: 'Unknown or expired task.', type: 'invalid_request_error', param: 'task_id', code: 'task_not_found' } },
  };
}

return {
  httpStatus: 200,
  responseJson: {
    task_id: $json.task_id,
    status: $json.status,
    model: $json.model,
    position: $json.position === null ? null : Number($json.position),
    attempts: $json.attempts,
    max_attempts: $json.max_attempts,
    created_at: $json.created_at,
    started_at: $json.started_at,
    completed_at: $json.completed_at,
    response_id: $json.response_id || null,
    error: $json.error_body || null,
  },
};

const models = String($json.configuredModelIds || 'queued-local-model')
  .split(',')
  .map((id) => id.trim())
  .filter(Boolean);
return {
  httpStatus: 200,
  responseJson: {
    object: 'list',
    data: models.map((id) => ({ id, object: 'model', created: 0, owned_by: 'local' })),
  },
};

const job = $('Assign Oldest Pending Task').first().json;
const config = $('Set GPU Dispatcher Params').first().json;
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const succeeded = statusCode >= 200 && statusCode < 300;
const retryable = [408, 425, 429].includes(statusCode) || statusCode >= 500;
const shouldRetry = !succeeded && retryable && Number(job.attempts) < Number(job.max_attempts);
const retryBaseSeconds = Math.max(1, Math.min(300, Math.trunc(Number(config.retryBaseSeconds) || 15)));

return {
  taskId: job.id,
  claimToken: job.claim_token,
  nextStatus: succeeded ? 'succeeded' : shouldRetry ? 'queued' : 'failed',
  responseBody: succeeded ? body : null,
  errorBody: succeeded ? null : {
    type: 'upstream_http_error',
    status_code: statusCode,
    response: body,
  },
  retryDelaySeconds: Math.min(300, retryBaseSeconds * Math.pow(2, Math.max(0, Number(job.attempts) - 1))),
};
